@@ -0,0 +1,22 @@
+// ps73_ms_plate_velocity.ogs — ps_7_3_r45 압밀 곡선 (시뮬레이션 시간 (ms)–판 속도 · 0 ms 부터 · 덱 설정 0.01 = 0.01 mm/s)
+// 사용: ps73_ms_plate_velocity.csv 를 가져온 워크북을 활성으로 두고 Script Window 에 붙여 넣기 → Enter.
+// 결과: 새 그래프 + BML 서식 · 단계 경계 점선 둘 (압축 시작 400.002 ms · 이완 시작 3125 ms).  C 열 (Source) 은 그리지 않는다.
+string bk$ = %H;
+plotxy iy:=[%(bk$)]1!(1,2) plot:=200 ogl:=<new>;
+set %C -c color(112,48,160); set %C -w 1500;
+layer.unit = 3; layer.width = 10; layer.height = 8;
+layer.x.color = color(64,64,64); layer.x.thickness = 1; layer.x.ticks = 10;
+layer.x.ticklength = 6; layer.x.tickthickness = 1; layer.x.mticklength = 3; layer.x.mtickthickness = 1;
+layer.x.label.font = font(Aptos); layer.x.label.pt = 28; layer.x.label.color = color(64,64,64);
+layer.y.color = color(64,64,64); layer.y.thickness = 1; layer.y.ticks = 10;
+layer.y.ticklength = 6; layer.y.tickthickness = 1; layer.y.mticklength = 3; layer.y.mtickthickness = 1;
+layer.y.label.font = font(Aptos); layer.y.label.pt = 28; layer.y.label.color = color(64,64,64);
+layer.x2.showAxes = 3; layer.x2.color = color(64,64,64); layer.x2.thickness = 1; layer.x2.ticks = 0; layer.x2.showLabels = 0;
+layer.y2.showAxes = 3; layer.y2.color = color(64,64,64); layer.y2.thickness = 1; layer.y2.ticks = 0; layer.y2.showLabels = 0;
+layer.x.from = 0; layer.x.to = 3250; layer.x.inc = 1000; layer.x.minor = 1;
+page.margincontrol = 1;
+label -xb Simulation time (ms);
+layer.y.from = 0; layer.y.to = 0.015; layer.y.inc = 0.005; layer.y.minor = 1;
+label -yl Plate velocity (mm/s);
+draw -n b2 -l -v 400.002; b2.linetype = 3; b2.color = color(154,160,168);
+draw -n b3 -l -v 3125.000; b3.linetype = 3; b3.color = color(154,160,168);
